/// <summary>
/// Gets or sets the value of the Transaction Id
/// </summary>
/// <param name = "_transactionId">Transaction id</param>
/// <returns>Transaction refrecid</returns>
[DataMember("@SYS25395"),
SysOperationLabelAttribute(literalstr("@SYS25395")),
SysOperationControlVisibilityAttribute(false)]
public CreatedTransactionId parmTransaction(CreatedTransactionId _transactionId = transactionId)
{
    transactionId = _transactionId;

    return transactionId;
}
